=== FILE: scenarios/01-coding-team.ts ===
import { H } from 'harness-dsl';
import type { PendingView } from 'harness-dsl';
import { z } from 'zod';
import * as claudeCode from 'harness-dsl/claude-code';
import * as anthropic from 'harness-dsl/anthropic';
import * as linear from 'harness-dsl/linear';
import * as folder from 'harness-dsl/folder';
import * as sqlite from 'harness-dsl/sqlite';
import * as jsonl from 'harness-dsl/jsonl';
import * as git from 'harness-dsl/git';
import * as shell from 'harness-dsl/shell';
import * as markdown from 'harness-dsl/markdown';

const ticketData = z.object({ title: z.string(), description: z.string() });

const ticketOpen = H.state('ticket-open', 'pending');
const ticketBuilding = H.state('ticket-building', 'active');
const ticketDone = H.state('ticket-done', 'terminal', 'success');
const ticketUnresolved = H.state('ticket-unresolved', 'terminal', 'failure');

const Bug = H.kind('bug').data(ticketData).states(ticketOpen, ticketBuilding, ticketDone, ticketUnresolved);
const Feature = H.kind('feature').data(ticketData).states(ticketOpen, ticketBuilding, ticketDone, ticketUnresolved);

const Epic = H.kind('epic')
  .data(ticketData)
  .states(
    H.state('epic-open', 'pending'),
    H.state('epic-planning', 'active'),
    H.state('epic-decomposed', 'waiting'),
    H.state('epic-done', 'terminal', 'success'),
    H.state('epic-incomplete', 'terminal', 'failure')
  );

const Heartbeat = H.kind('service-heartbeat')
  .data(z.object({ service: z.string() }))
  .states(
    H.state('beat-due', 'pending'),
    H.state('beating', 'active'),
    H.state('beat-ok', 'terminal', 'success'),
    H.state('beat-failed', 'terminal', 'failure')
  );

const experience = H.memory('coding-experience', 'experience');
const taste = H.memory('owner-taste', 'taste');
const experienceLibrary = H.library('coding-lessons', experience, jsonl.memory('.harness/experience.jsonl'));
const tasteLibrary = H.library('owner-preferences', taste, jsonl.memory('.harness/taste.jsonl'));

const sonnet = anthropic.model('claude-sonnet-4-5');
const opus = anthropic.model('claude-opus-4-1');

const builderModel = H.policy.model('builder-model', ({ kind, metrics }) => {
  const cheap = metrics.successRate({ kind, model: sonnet, days: 14 });
  const enoughSamples = cheap.samples >= 20;
  const tooWeak = cheap.value !== null && cheap.value < 0.85;
  return enoughSamples && tooWeak ? opus : sonnet;
});

const builderRole = H.role('builder')
  .input(z.object({
    title: z.string(),
    description: z.string(),
    deficits: z.array(z.string()),
    guidance: z.string()
  }))
  .output(z.object({ summary: z.string(), question: z.string().optional() }))
  .prompt((input) => [
    `Implement: ${input.title}`,
    input.description,
    input.deficits.length > 0 ? `Fix these deficits first:\n- ${input.deficits.join('\n- ')}` : '',
    input.guidance.length > 0 ? `Owner guidance: ${input.guidance}` : '',
    'If a decision belongs to the owner, return it as a question instead of guessing.'
  ].join('\n\n'))
  .intents(['read', 'edit', 'execute']);

const auditorRole = H.role('auditor')
  .input(z.object({ title: z.string(), description: z.string(), summary: z.string() }))
  .output(z.object({ deficits: z.array(z.string()) }))
  .prompt((input) => `Audit the change for "${input.title}".\n\n${input.description}\n\nBuilder summary:\n${input.summary}\n\nList every remaining deficit; an empty list means done.`)
  .intents(['read', 'execute']);

const plannerRole = H.role('planner')
  .input(z.object({ title: z.string(), description: z.string() }))
  .output(z.object({ features: z.array(z.object({ title: z.string(), description: z.string() })) }))
  .prompt((input) => `Decompose the epic "${input.title}" into independently shippable features.\n\n${input.description}`)
  .intents(['read']);

const worktrees = git.worktree('builder-worktrees', { repo: '.', slots: 3 });
const localShell = shell.local('local-shell', { slots: 4 });

const projectChecks = H.command('project-checks').argv(() => ['npm', 'run', 'check']);

const builder = H.agent('builder', builderRole)
  .model(builderModel)
  .on(worktrees)
  .recalls(experienceLibrary, tasteLibrary)
  .guards(claudeCode.fileLeases(), claudeCode.stopCheck(projectChecks));

const auditor = H.agent('auditor', auditorRole)
  .model(opus)
  .on(worktrees)
  .recalls(experienceLibrary)
  .records(experienceLibrary);

const planner = H.agent('planner', plannerRole).model(opus).recalls(tasteLibrary);

const ownerDecision = H.halt('owner-decision', z.object({ answer: z.string() }));

const ticketWork = H.flow('ticket-work')
  .for(Bug, Feature)
  .params(z.object({ rounds: z.number().int().positive() }))
  .does(async (ctx) => {
    const { title, description } = ctx.unit.data;
    let deficits: string[] = [];
    let guidance = '';
    let round = 0;
    await ctx.move('ticket-building');
    while (round < ctx.params.rounds) {
      const built = await ctx.run(builder, { title, description, deficits, guidance });
      if (!built.ok) return ctx.fail(built.error);
      const question = built.value.question;
      if (question !== undefined) {
        const decision = await ctx.halt(ownerDecision, question);
        guidance = decision.answer;
        continue;
      }
      round += 1;
      const audited = await ctx.run(auditor, { title, description, summary: built.value.summary });
      if (!audited.ok) return ctx.fail(audited.error);
      if (audited.value.deficits.length === 0) return 'ticket-done';
      deficits = audited.value.deficits;
    }
    return 'ticket-unresolved';
  });

const heartbeatCommand = H.command('service-health-check')
  .input(z.object({ service: z.string() }))
  .argv(({ service }) => ['curl', '-fsS', '--max-time', '10', `https://${service}.internal/health`])
  .on(localShell);

const heartbeatWork = H.flow('heartbeat-check')
  .for(Heartbeat)
  .does(async (ctx) => {
    await ctx.move('beating');
    const checked = await ctx.run(heartbeatCommand, { service: ctx.unit.data.service });
    return checked.ok ? 'beat-ok' : 'beat-failed';
  });

const linearKey = H.env('LINEAR_API_KEY');
const ticketStatuses = {
  'ticket-open': 'Todo',
  'ticket-building': 'In Progress',
  'ticket-done': 'Done',
  'ticket-unresolved': 'Needs Attention'
};

const bugTracker = linear.tracker(Bug, {
  apiKey: linearKey,
  team: 'product',
  label: 'bug',
  read: (issue) => ({ title: issue.title, description: issue.description }),
  statuses: ticketStatuses
});

const featureTracker = linear.tracker(Feature, {
  apiKey: linearKey,
  team: 'product',
  label: 'feature',
  read: (issue) => ({ title: issue.title, description: issue.description }),
  statuses: ticketStatuses
});

const epicTracker = linear.tracker(Epic, {
  apiKey: linearKey,
  team: 'product',
  label: 'epic',
  read: (issue) => ({ title: issue.title, description: issue.description }),
  statuses: {
    'epic-open': 'Todo',
    'epic-planning': 'In Progress',
    'epic-decomposed': 'In Progress',
    'epic-done': 'Done',
    'epic-incomplete': 'Needs Attention'
  }
});

const bugFolder = folder.files(Bug, {
  dir: 'bugs',
  read: (file) => {
    const title = file.frontmatter['title'];
    return { title: typeof title === 'string' ? title : file.path, description: file.body };
  }
});

const bugLane = H.lane('bugs', Bug)
  .handler(ticketWork, { params: { rounds: 3 } })
  .suppliers(bugTracker, bugFolder, H.operator)
  .store(bugTracker)
  .wip(2);

const featureLane = H.lane('features', Feature)
  .handler(ticketWork, { params: { rounds: 5 } })
  .suppliers(featureTracker, H.operator)
  .store(featureTracker);

const epicWork = H.flow('epic-work')
  .for(Epic)
  .does(async (ctx) => {
    await ctx.move('epic-planning');
    const plan = await ctx.run(planner, { title: ctx.unit.data.title, description: ctx.unit.data.description });
    if (!plan.ok) return ctx.fail(plan.error);
    const features = await ctx.spawn(featureLane, plan.value.features);
    const finished = await ctx.wait('epic-decomposed', { children: features });
    return finished.every((feature) => feature.state === 'ticket-done') ? 'epic-done' : 'epic-incomplete';
  });

const epicLane = H.lane('epics', Epic)
  .handler(epicWork)
  .suppliers(epicTracker)
  .store(epicTracker)
  .wip(1);

const services = ['api', 'web', 'worker'];

const heartbeatLane = H.lane('heartbeats', Heartbeat)
  .handler(heartbeatWork)
  .suppliers(H.clock('heartbeat-schedule', Heartbeat, { every: { minutes: 5 } }, ({ now }) =>
    services.map((service) => Heartbeat.create({ service }, `${service}-${now.toISOString()}`))));

const heartbeatBug = H.trigger('failed-heartbeat-files-bug', H.on.enters(Heartbeat, 'beat-failed'), (event, act) =>
  act.create(bugLane, {
    title: `Heartbeat failed for ${event.unit.data.service}`,
    description: `The deterministic health check for ${event.unit.data.service} failed at ${event.at.toISOString()}.`
  }, `heartbeat-${event.unit.data.service}-${event.at.toISOString()}`));

const max1 = claudeCode.subscription('claude-max-1', { token: H.env('CLAUDE_MAX_TOKEN_1') });
const max2 = claudeCode.subscription('claude-max-2', { token: H.env('CLAUDE_MAX_TOKEN_2') });
const max3 = claudeCode.subscription('claude-max-3', { token: H.env('CLAUDE_MAX_TOKEN_3') });
const apiAccount = anthropic.account('anthropic-api', { apiKey: H.env('ANTHROPIC_API_KEY') });

const drainSoonestExpiring = H.policy.account('drain-soonest-expiring', ({ accounts }) => {
  const subscriptions = accounts
    .filter((view) => view.eligible && view.account.plan === 'subscription' && view.usedShare < view.share)
    .sort((a, b) => (a.windowEndsAt?.getTime() ?? Infinity) - (b.windowEndsAt?.getTime() ?? Infinity));
  const soonest = subscriptions[0];
  if (soonest !== undefined) return soonest.account;
  const fallback = accounts.find((view) => view.eligible && view.account === apiAccount);
  return fallback === undefined ? null : fallback.account;
});

const claudePool = H.pool('claude-accounts', [
  { account: max1, share: 0.5 },
  { account: max2, share: 0.3 },
  { account: max3, share: 0.2 },
  { account: apiAccount, share: 1 }
], drainSoonestExpiring);

const featureStarvationMs = 2 * 60 * 60 * 1000;

const rank = (unit: PendingView): number => {
  if (unit.is(Heartbeat)) return 0;
  if (unit.is(Feature) && unit.waitedMs > featureStarvationMs) return 1;
  if (unit.is(Bug)) return 2;
  if (unit.is(Feature)) return 3;
  return 4;
};

const priority = H.policy.scheduler('heartbeats-bugs-features-epics', ({ pending }) => ({
  start: [...pending].sort((a, b) => rank(a) - rank(b) || b.waitedMs - a.waitedMs)
}));

const productionHealthProbe = H.command('production-health-probe')
  .argv(() => ['curl', '-fsS', 'https://app.example.com/health'])
  .on(localShell);

const supervisor = claudeCode.supervisor({
  grants: [
    H.ops.readWork,
    H.ops.writeWork,
    H.ops.resolveHalts,
    H.ops.writeMemory,
    H.ops.readTelemetry,
    H.ops.readAccounts,
    H.ops.setShares,
    H.operation('production-health', productionHealthProbe)
  ]
});

export default H.harness('coding-team')
  .ledger(sqlite.ledger('.harness/coding-team.db'))
  .lanes(heartbeatLane, bugLane, featureLane, epicLane)
  .pools(claudePool)
  .triggers(heartbeatBug)
  .scheduler(priority)
  .clients(supervisor)
  .observers(markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md'));
=== END ===

=== FILE: scenarios/02-support-triage.ts ===
import { H } from 'harness-dsl';
import type { ModelPolicy, PendingView } from 'harness-dsl';
import { z } from 'zod';
import * as claudeCode from 'harness-dsl/claude-code';
import * as anthropic from 'harness-dsl/anthropic';
import * as http from 'harness-dsl/http';
import * as sqlite from 'harness-dsl/sqlite';
import * as jsonl from 'harness-dsl/jsonl';
import * as shell from 'harness-dsl/shell';
import * as markdown from 'harness-dsl/markdown';

const Conversation = H.kind('conversation')
  .data(z.object({
    customer: z.string(),
    lastMessage: z.string(),
    slaDueAt: z.string(),
    category: z.string().optional()
  }))
  .states(
    H.state('new', 'pending'),
    H.state('classifying', 'active'),
    H.state('drafting', 'active'),
    H.state('awaiting-approval', 'active'),
    H.state('sent', 'terminal', 'success'),
    H.state('closed-by-customer', 'terminal', 'neutral'),
    H.state('escalated', 'terminal', 'failure')
  );

const Escalation = H.kind('escalation')
  .data(z.object({ conversationId: z.string(), customer: z.string(), reason: z.string() }))
  .states(
    H.state('escalation-open', 'pending'),
    H.state('escalation-active', 'active'),
    H.state('escalation-resolved', 'terminal', 'success'),
    H.state('escalation-dropped', 'terminal', 'neutral')
  );

const category = H.tag('category');

const tasteLibrary = H.library('support-tone', H.memory('support-taste', 'taste'), jsonl.memory('.harness/support-taste.jsonl'));
const experienceLibrary = H.library('support-lessons', H.memory('support-experience', 'experience'), jsonl.memory('.harness/support-experience.jsonl'));

const haiku = anthropic.model('claude-haiku-4-5');
const sonnet = anthropic.model('claude-sonnet-4-5');
const opus = anthropic.model('claude-opus-4-1');

const replyApproval = H.halt('reply-approval', z.object({
  approved: z.boolean(),
  reply: z.string().optional(),
  tasteNote: z.string().optional()
}));

const escalationResolution = H.halt('escalation-resolution', z.object({ resolved: z.boolean(), note: z.string() }));

const classifierRole = H.role('classifier')
  .input(z.object({ message: z.string() }))
  .output(z.object({ category: z.enum(['billing', 'refund', 'technical', 'account', 'other']) }))
  .prompt((input) => `Classify this customer message into one category.\n\n${input.message}`);

const drafterRole = H.role('drafter')
  .input(z.object({ message: z.string(), category: z.string() }))
  .output(z.object({ reply: z.string() }))
  .prompt((input) => `Draft a reply to this ${input.category} conversation.\n\n${input.message}`);

const drafterModel: ModelPolicy = H.policy.model('drafter-model', ({ metrics }) => {
  const byModel = metrics.rateBy({
    among: replyApproval.resolved(),
    count: replyApproval.resolved({ approved: true }),
    by: { model: drafter },
    days: 30
  });
  const sonnetRate = byModel.get(sonnet);
  const opusRate = byModel.get(opus);
  if (sonnetRate.samples < 50 || opusRate.samples < 50) {
    return sonnetRate.samples <= opusRate.samples ? sonnet : opus;
  }
  return (sonnetRate.value ?? 0) >= (opusRate.value ?? 0) - 0.02 ? sonnet : opus;
});

const classifier = H.agent('classifier', classifierRole).model(haiku);
const drafter = H.agent('drafter', drafterRole).model(drafterModel).recalls(tasteLibrary, experienceLibrary);

const autoSendSafe = H.policy.rule('auto-send-safe')
  .input(z.object({ category: z.string() }))
  .decides((input, metrics) => {
    const approvals = metrics.rate({
      among: replyApproval.resolved().where(category, input.category),
      count: replyApproval.resolved({ approved: true }).where(category, input.category)
    });
    return approvals.samples >= 200 && approvals.hits === approvals.samples;
  });

const localShell = shell.local('local-shell', { slots: 4 });
const helpdeskAuth = H.env('HELPDESK_AUTH_HEADER');

const sendReply = H.command('send-reply')
  .input(z.object({ conversationId: z.string(), reply: z.string() }))
  .argv((input) => [
    'curl', '-fsS', '-X', 'POST',
    '-H', helpdeskAuth,
    '-H', 'Content-Type: application/json',
    `https://helpdesk.example.com/api/conversations/${input.conversationId}/replies`,
    '-d', JSON.stringify({ body: input.reply })
  ])
  .on(localShell)
  .recovery('park');

const conversationWork = H.flow('conversation-work')
  .for(Conversation)
  .does(async (ctx) => {
    const message = ctx.unit.data.lastMessage;
    await ctx.move('classifying');
    const classified = await ctx.run(classifier, { message });
    if (!classified.ok) return ctx.fail(classified.error);
    const chosen = classified.value.category;
    ctx.tag(category, chosen);
    await ctx.update({ category: chosen });

    await ctx.move('drafting');
    const drafted = await ctx.run(drafter, { message, category: chosen });
    if (!drafted.ok) return ctx.fail(drafted.error);
    let reply = drafted.value.reply;

    const safe = await ctx.decide(autoSendSafe, { category: chosen });
    if (!safe) {
      await ctx.move('awaiting-approval');
      const review = await ctx.halt(replyApproval, `Category: ${chosen}\n\n${reply}`);
      if (review.tasteNote !== undefined) {
        await ctx.remember(tasteLibrary, {
          text: review.tasteNote,
          because: `reviewer edited a ${chosen} reply`,
          when: { roles: [drafterRole] },
          status: 'candidate'
        });
      }
      if (!review.approved) return 'escalated';
      reply = review.reply ?? reply;
    }

    const sent = await ctx.run(sendReply, { conversationId: ctx.unit.key, reply });
    if (!sent.ok) return ctx.fail(sent.error);
    return 'sent';
  });

const escalationWork = H.flow('escalation-handling')
  .for(Escalation)
  .does(async (ctx) => {
    await ctx.move('escalation-active');
    const outcome = await ctx.halt(
      escalationResolution,
      `Conversation ${ctx.unit.data.conversationId} with ${ctx.unit.data.customer} escalated: ${ctx.unit.data.reason}`
    );
    return outcome.resolved ? 'escalation-resolved' : 'escalation-dropped';
  });

const helpdeskWebhook = http.webhook(Conversation, {
  path: '/hooks/helpdesk',
  secret: H.env('HELPDESK_WEBHOOK_SECRET'),
  body: z.object({
    event: z.enum(['conversation.created', 'message.created', 'conversation.closed']),
    conversationId: z.string(),
    customer: z.string(),
    message: z.string(),
    slaDueAt: z.string()
  }),
  read: (body) => {
    switch (body.event) {
      case 'conversation.created':
        return Conversation.create({ customer: body.customer, lastMessage: body.message, slaDueAt: body.slaDueAt }, body.conversationId);
      case 'message.created':
        return Conversation.update(body.conversationId, { patch: { lastMessage: body.message }, state: 'new' });
      case 'conversation.closed':
        return Conversation.update(body.conversationId, { state: 'closed-by-customer' });
    }
  }
});

const helpdeskPoll = http.poll(Conversation, {
  url: 'https://helpdesk.example.com/api/conversations?status=open',
  every: { minutes: 10 },
  headers: { Authorization: helpdeskAuth },
  body: z.object({
    conversations: z.array(z.object({
      id: z.string(),
      customer: z.string(),
      lastMessage: z.string(),
      slaDueAt: z.string()
    }))
  }),
  read: (body) => body.conversations.map((item) =>
    Conversation.create({ customer: item.customer, lastMessage: item.lastMessage, slaDueAt: item.slaDueAt }, item.id))
});

const helpdeskStore = http.store(Conversation, {
  url: 'https://helpdesk.example.com/api/conversations',
  headers: { Authorization: helpdeskAuth },
  stateField: 'harness_state'
});

const conversationLane = H.lane('conversations', Conversation)
  .handler(conversationWork)
  .suppliers(helpdeskWebhook, helpdeskPoll)
  .store(helpdeskStore)
  .maxUsdPerUnit(0.4);

const escalationLane = H.lane('escalations', Escalation).handler(escalationWork);

const slaBreach = H.trigger(
  'sla-breach-escalates',
  H.on.deadline(Conversation, (data) => new Date(data.slaDueAt), ['new', 'classifying', 'drafting', 'awaiting-approval']),
  (_event, act) => act.move('escalated')
);

const escalationOpens = H.trigger('escalated-conversation-opens-escalation', H.on.enters(Conversation, 'escalated'), (event, act) =>
  act.create(escalationLane, {
    conversationId: event.unit.key,
    customer: event.unit.data.customer,
    reason: event.unit.data.lastMessage
  }, `escalation-${event.unit.key}`));

const breachTime = (unit: PendingView): number => {
  if (unit.is(Escalation)) return Number.NEGATIVE_INFINITY;
  if (unit.is(Conversation)) return Date.parse(unit.data.slaDueAt);
  return Number.POSITIVE_INFINITY;
};

const byTimeToBreach = H.policy.scheduler('time-to-breach', ({ pending }) => ({
  start: [...pending].sort((a, b) => breachTime(a) - breachTime(b))
}));

const apiPool = H.pool('support-accounts', [
  { account: anthropic.account('support-api', { apiKey: H.env('ANTHROPIC_API_KEY') }), share: 1 }
]);

export default H.harness('support-triage')
  .ledger(sqlite.ledger('.harness/support.db'))
  .lanes(conversationLane, escalationLane)
  .pools(apiPool)
  .triggers(slaBreach, escalationOpens)
  .scheduler(byTimeToBreach)
  .clients(claudeCode.supervisor({
    grants: [H.ops.readWork, H.ops.writeWork, H.ops.resolveHalts, H.ops.readMemory, H.ops.writeMemory, H.ops.readTelemetry]
  }))
  .observers(markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md'));
=== END ===

=== FILE: scenarios/03-research-pipeline.ts ===
import { H } from 'harness-dsl';
import type { ModelPolicy } from 'harness-dsl';
import { z } from 'zod';
import * as claudeCode from 'harness-dsl/claude-code';
import * as anthropic from 'harness-dsl/anthropic';
import * as sqlite from 'harness-dsl/sqlite';
import * as jsonl from 'harness-dsl/jsonl';
import * as qdrant from 'harness-dsl/qdrant';
import * as shell from 'harness-dsl/shell';
import * as markdown from 'harness-dsl/markdown';

const Topic = H.kind('topic')
  .data(z.object({
    question: z.string(),
    tags: z.array(z.string()),
    report: z.string().optional()
  }))
  .states(
    H.state('topic-queued', 'pending'),
    H.state('researching', 'active'),
    H.state('topic-reported', 'terminal', 'success'),
    H.state('topic-parked', 'terminal', 'neutral'),
    H.state('topic-cancelled', 'terminal', 'neutral')
  );

const findingsLibrary = H.library(
  'prior-report-findings',
  H.memory('report-findings', 'experience'),
  qdrant.memory({
    url: 'https://vectors.internal:6333',
    collection: 'report-findings',
    embedder: 'text-embedding-small',
    apiKey: H.env('VECTOR_STORE_KEY')
  })
);

const sourceLessons = H.library(
  'source-lessons',
  H.memory('source-experience', 'experience'),
  jsonl.memory('.harness/source-experience.jsonl')
);

const haiku = anthropic.model('claude-haiku-4-5');
const sonnet = anthropic.model('claude-sonnet-4-5');
const opus = anthropic.model('claude-opus-4-1');

const searchSlices = 20;
const minimumFindings = 5;

const searcherRole = H.role('searcher')
  .input(z.object({ question: z.string(), slice: z.number(), of: z.number() }))
  .output(z.object({ findings: z.array(z.object({ claim: z.string(), source: z.string() })) }))
  .prompt((input) => `Search angle ${input.slice + 1} of ${input.of} for: ${input.question}\nExtract sourced claims with resolvable URLs.`)
  .intents(['browse']);

const synthesizerRole = H.role('synthesizer')
  .input(z.object({
    question: z.string(),
    findings: z.array(z.object({ claim: z.string(), source: z.string() }))
  }))
  .output(z.object({ report: z.string(), headline: z.string(), citations: z.array(z.string()) }))
  .prompt((input) => `Write a sourced report answering: ${input.question}\n\nFindings:\n${input.findings.map((f) => `- ${f.claim} (${f.source})`).join('\n')}`);

const localShell = shell.local('local-shell', { slots: 2 });

const citationCheck = H.command('citation-check')
  .input(z.object({ citations: z.array(z.string()) }))
  .argv((input) => ['./tools/check-citations', ...input.citations])
  .on(localShell);

const synthesizerModel: ModelPolicy = H.policy.model('synthesizer-model', ({ metrics }) => {
  const passRate = metrics.rateBy({
    among: citationCheck.invocations(),
    count: citationCheck.invocations({ ok: true }),
    by: { model: synthesizer },
    days: 30
  });
  const sonnetRate = passRate.get(sonnet);
  const opusRate = passRate.get(opus);
  if (sonnetRate.samples < 20 || opusRate.samples < 20) {
    return sonnetRate.samples <= opusRate.samples ? sonnet : opus;
  }
  return (sonnetRate.value ?? 0) >= (opusRate.value ?? 0) ? sonnet : opus;
});

const searcher = H.agent('searcher', searcherRole).model(haiku).recalls(sourceLessons);
const synthesizer = H.agent('synthesizer', synthesizerRole)
  .model(synthesizerModel)
  .recalls(findingsLibrary, sourceLessons)
  .records(sourceLessons);

const research = H.flow('research')
  .for(Topic)
  .does(async (ctx) => {
    const question = ctx.unit.data.question;
    await ctx.move('researching');

    const searches = await ctx.batch(
      searcher,
      Array.from({ length: searchSlices }, (_, slice) => ({ question, slice, of: searchSlices }))
    );
    const findings = searches.flatMap((result) => (result.ok ? result.value.findings : []));
    if (findings.length < minimumFindings) return 'topic-parked';

    const synthesized = await ctx.run(synthesizer, { question, findings });
    if (!synthesized.ok) return ctx.fail(synthesized.error);

    const checked = await ctx.run(citationCheck, { citations: synthesized.value.citations });
    if (!checked.ok) return ctx.fail(`citation did not resolve: ${checked.error}`);

    await ctx.update({ report: synthesized.value.report });
    await ctx.remember(findingsLibrary, {
      text: `When researching a question like "${question}", start from: ${synthesized.value.headline}`,
      because: `report ${ctx.unit.key} established it with ${synthesized.value.citations.length} resolved citations`,
      when: { kinds: [Topic], roles: [synthesizerRole] },
      status: 'accepted'
    });
    return 'topic-reported';
  });

const recurringReopen = H.clock('recurring-topics', Topic, { weekly: { day: 'mon', at: '06:00' } }, ({ units }) =>
  units
    .filter((unit) => unit.position === 'terminal' && unit.data.tags.includes('recurring'))
    .map((unit) => Topic.update(unit.key, { state: 'topic-queued' })));

const topicCeilingUsd = 3;
const dailyBudgetUsd = 40;

const topicLane = H.lane('topics', Topic)
  .handler(research)
  .suppliers(H.operator, recurringReopen)
  .store(sqlite.store(Topic, '.harness/topics.db'))
  .maxUsdPerUnit(topicCeilingUsd);

const withinDailyBudget = H.policy.scheduler('daily-budget', ({ now, pending, active, metrics }) => {
  const midnight = new Date(now);
  midnight.setHours(0, 0, 0, 0);
  const spentToday = metrics.sum({ of: 'costUsd', among: Topic.attempts(), since: midnight }).value ?? 0;
  const succeededCost = metrics.mean({ of: 'costUsd', among: Topic.attempts({ outcome: 'succeeded' }), days: 30 });
  const projectedUsd = succeededCost.samples >= 5 && succeededCost.value !== null ? succeededCost.value : topicCeilingUsd;
  const remainingUsd = dailyBudgetUsd - spentToday - projectedUsd * active.length;
  const affordable = Math.max(0, Math.floor(remainingUsd / projectedUsd));
  return { start: pending.slice(0, affordable) };
});

const batchPool = H.pool('research-accounts', [
  { account: anthropic.account('research-api', { apiKey: H.env('ANTHROPIC_API_KEY') }), share: 1 }
]);

export default H.harness('research-pipeline')
  .ledger(sqlite.ledger('.harness/research.db'))
  .lanes(topicLane)
  .pools(batchPool)
  .scheduler(withinDailyBudget)
  .clients(claudeCode.supervisor({
    grants: [H.ops.readWork, H.ops.writeWork, H.ops.resolveHalts, H.ops.readMemory, H.ops.writeMemory, H.ops.readTelemetry]
  }))
  .observers(markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md'));
