    routeConversation,
  )
  .supply(
    zendesk.poll({ subdomain: 'acme', token: H.env('ZENDESK_TOKEN'), everyMinutes: 10 }),
    routeConversation,
  )
  .store(zendesk.store({ subdomain: 'acme', token: H.env('ZENDESK_TOKEN') }), {
    New: 'new',
    Classifying: 'open',
    Drafting: 'open',
    AwaitingApproval: 'open',
    Sending: 'open',
    Sent: 'solved',
    ClosedByCustomer: 'closed',
