  .runner(i => i.host === 'a' ? hostA : hostB);

const renewCertificate = H.command('renewCertificate')
  .input(z.object({ domain: z.string(), host: z.enum(['a', 'b']) }))
  .argv(i => ['renew-cert', i.domain])
