  .exit('resolved', ctx => ctx.steps.confirm.resolved)
  .exit('unresolved');

const services = ['api', 'web', 'queue'];
const databases = [
  { database: 'orders', host: 'a' as const },
  { database: 'customers', host: 'b' as const },
];
const domains = [
