const AwaitingApproval = H.state('AwaitingApproval', 'waiting');
const Sending = H.state('Sending', 'active');
const Sent = H.terminal('Sent', 'success');
const ClosedByCustomer = H.terminal('ClosedByCustomer', 'neutral');
const Escalated = H.terminal('Escalated', 'failure');

const Conversation = H.kind('Conversation')
  .attributes(conversationAttrs)
  .states(New, Classifying, Drafting, AwaitingApproval, Sending, Sent, ClosedByCustomer, Escalated)
  .key((attrs) => attrs.ticketId)
  .initial(New);

const EscalationOpen = H.state('EscalationOpen', 'pending');
const WithHuman = H.state('WithHuman', 'waiting');
const Handled = H.terminal('Handled', 'success');
const Unhandled = H.terminal('Unhandled', 'failure');

const Escalation = H.kind('Escalation')
  .attributes(escalationAttrs)
  .states(EscalationOpen, WithHuman, Handled, Unhandled)
  .key((attrs) => attrs.ticketId)
  .initial(EscalationOpen);

const replyDuringApproval = H.signal('replyDuringApproval').payload(z.object({ message: z.string() }));
const replyNoted = H.signal('replyNoted').payload(z.object({ message: z.string() }));
const customerClosed = H.signal('customerClosed');
const slaBreached = H.signal('slaBreached');

const classifierRole = H.role('classifier').intents('read').instructions('Assign the conversation one support category.');
const drafterRole = H.role('drafter').intents('read', 'search').instructions('Draft the next reply to the customer.');
const reviewerRole = H.role('reviewer').instructions('Approve, edit or reject outgoing replies.');

const apiAccount = anthropic.account('support-api', { apiKey: H.env('ANTHROPIC_API_KEY') });
const support = H.pool('support').accounts(apiAccount);

const haiku = anthropic.model('haiku', { id: 'claude-haiku-4-5' });
const sonnet = anthropic.model('sonnet', { id: 'claude-sonnet-4-5' });

const classifier = H.agent('classifier')
  .role(classifierRole)
  .model(haiku)
  .pool(support)
  .output(z.object({ category: z.string() }));

const drafter = H.agent('drafter')
  .role(drafterRole)
  .model(sonnet)
  .pool(support)
  .output(z.object({ reply: z.string() }));

const localRunner = local.runner('local');

const sendReply = H.command('send-reply')
  .input(z.object({ ticketId: z.string(), reply: z.string() }))
  .argv((input) => ['./support/send-reply.sh', input.ticketId, input.reply])
  .runner(localRunner);

const approvalDecision = z.object({
  approved: z.boolean(),
  reply: z.string(),
  notes: z.string().optional(),
  auto: z.boolean().optional(),
});

function isSafeCategory(metrics: Metrics, category: string): boolean {
  const approvals = metrics.rate(humanApprovalByCategory, { group: category });
  return approvals.samples >= 200 && approvals.hits === approvals.samples;
}

const triage = H.flow('triage')
  .input(conversationAttrs)
  .step('classify', classifier, (ctx) => ({
    task: `Classify this conversation.\n\nSubject: ${ctx.unit.attributes.subject}\n\n${ctx.unit.attributes.message}`,
  }))
  .loop(
    'drafting',
    (round) =>
      round
        .step('draft', drafter, (ctx) => ({
          task: `Draft a reply to ${ctx.unit.attributes.customerEmail}.\n\nSubject: ${ctx.unit.attributes.subject}\n\n${ctx.unit.attributes.message}`,
          skills: [ctx.steps.classify.category],
        }))
        .halt('approval', {
          ask: (ctx) => `Approve this reply in category ${ctx.steps.classify.category}:\n\n${ctx.steps.draft.reply}`,
          decision: approvalDecision,
          skip: (ctx) =>
            isSafeCategory(ctx.metrics, ctx.steps.classify.category)
              ? { approved: true, reply: ctx.steps.draft.reply, auto: true }
              : undefined,
        }),
    { max: 3, until: (ctx) => ctx.steps.approval.approved },
  )
  .exit('unapproved', (ctx) => !ctx.steps.approval.approved)
  .step('send', sendReply, (ctx) => ({ ticketId: ctx.unit.attributes.ticketId, reply: ctx.steps.approval.reply }), {
    afterCrash: 'park',
  })
  .exit('sent');

const humanEscalation = H.flow('human-escalation')
  .input(escalationAttrs)
  .halt('handle', {
    ask: (ctx) =>
      `Conversation ${ctx.unit.attributes.ticketId} (${ctx.unit.attributes.subject}) was escalated: ${ctx.unit.attributes.reason}. Resolve it with the customer and record what you did.`,
    decision: z.object({ resolution: z.string() }),
  })
  .exit('handled');

const slaHours = { low: 48, normal: 24, high: 8, urgent: 2 };

function routeHelpdesk(event: ZendeskEvent, to: Router<ConversationAttrs, string>): Route | readonly Route[] {
  if (event.type === 'created') {
    return to.create({
      ticketId: event.ticketId,
      subject: event.subject,
      message: event.message,
      customerEmail: event.customerEmail,
      slaDueAt: new Date(event.createdAt.getTime() + slaHours[event.priority] * 3_600_000).toISOString(),
    });
  }
  if (event.status === 'solved' || event.status === 'closed') {
    return to.signal(customerClosed, event.ticketId, {});
  }
  if (event.type === 'replied') {
    return [
      to.signal(
        replyDuringApproval,
        (unit) => unit.key === event.ticketId && unit.attempt?.step === 'approval',
        { message: event.message },
      ),
      to.signal(
        replyNoted,
        (unit) => unit.key === event.ticketId && unit.attempt?.step !== 'approval',
        { message: event.message },
      ),
    ];
  }
  return to.skip();
}

const escalations = H.lane('escalations', Escalation)
  .handler(humanEscalation, { exits: { handled: Handled }, during: { handle: WithHuman } })
  .retry({ maxAttempts: 2, backoff: 'fixed', initialDelayMs: 60_000, exhausted: Unhandled });

const conversations = H.lane('conversations', Conversation)
  .supply(
    zendesk.webhook({ port: H.slot.port(0), path: '/helpdesk', secret: H.env('ZENDESK_WEBHOOK_SECRET') }),
    routeHelpdesk,
  )
  .supply(zendesk.poll({ subdomain: 'acme', token: H.env('ZENDESK_TOKEN'), everyMinutes: 10 }), routeHelpdesk)
  .store(zendesk.store({ subdomain: 'acme', token: H.env('ZENDESK_TOKEN') }))
  .handler(triage, {
    exits: { unapproved: Escalated, sent: Sent },
    during: { classify: Classifying, draft: Drafting, approval: AwaitingApproval, send: Sending },
  })
  .retry({ maxAttempts: 3, backoff: 'exponential', initialDelayMs: 30_000, exhausted: Escalated })
  .ceiling({ maxUsd: 0.4, onExceed: 'halt' })
  .on(replyDuringApproval, {
    update: (attrs, payload) => ({ ...attrs, message: payload.message }),
    restart: 'classify',
  })
  .on(replyNoted, { update: (attrs, payload) => ({ ...attrs, message: payload.message }) })
  .on(customerClosed, { enter: ClosedByCustomer })
  .on(slaBreached, { enter: Escalated });

const humanApprovalByCategory: MetricRef<'rate'> = H.metric(
  'human-approval-by-category',
  H.when.step(conversations, 'approval'),
).samples((event) =>
  event.output === undefined || event.output.auto === true
    ? []
    : [{ group: event.outputs.classify?.category ?? 'unclassified', hit: event.output.approved }],
);

const humanApprovalByModel: MetricRef<'rate'> = H.metric(
  'human-approval-by-model',
  H.when.step(conversations, 'approval'),
).samples((event) =>
  event.output === undefined || event.output.auto === true
    ? []
    : [{ group: event.models.draft ?? 'unknown', hit: event.output.approved }],
);

const supportTaste = H.journal('support-taste', H.memory('support-taste', 'taste'))
  .store(jsonl.memoryStore({ path: '.harness/taste.jsonl' }))
  .recall({ by: 'specificity', limit: 10 })
  .readBy(drafterRole)
  .recordedBy(reviewerRole);

const supportExperience = H.journal('support-experience', H.memory('support-experience', 'experience'))
  .store(jsonl.memoryStore({ path: '.harness/experience.jsonl' }))
  .recall({ by: 'specificity', limit: 10 })
  .readBy(drafterRole)
  .recordedBy(reviewerRole);

const slaBreachEscalates = H.trigger('sla-breach-escalates')
  .on(H.when.timer(conversations, { at: (unit) => new Date(unit.attributes.slaDueAt) }))
  .create(escalations, (event) => ({
    ticketId: event.unit.attributes.ticketId,
    subject: event.unit.attributes.subject,
    reason: `SLA breached at ${event.at.toISOString()}`,
  }))
  .signal(slaBreached, conversations, (event) => ({ key: event.unit.key, payload: {} }));

const escalatedConversationNeedsHuman = H.trigger('escalated-conversation-needs-human')
  .on(H.when.transition(conversations, { to: Escalated }))
  .create(escalations, (event) => ({
    ticketId: event.unit.attributes.ticketId,
    subject: event.unit.attributes.subject,
    reason: 'no approved reply could be sent',
  }));

const reviewerNotesBecomeTaste = H.trigger('reviewer-notes-become-taste')
  .on(H.when.step(conversations, 'approval'))
  .record(supportTaste, (event) => {
    const notes = event.output?.notes;
    const category = event.outputs.classify?.category;
    return notes === undefined
      ? undefined
      : {
          text: notes,
          when: { kinds: [Conversation], roles: [drafterRole], skills: category === undefined ? [] : [category] },
          status: 'candidate',
        };
  });

const scheduler = H.scheduler('support')
  .priority(escalations, conversations)
  .rank(conversations, (unit) => new Date(unit.attributes.slaDueAt).getTime());

const supervisor = claudeCode.supervisor('reviewer-supervisor', {
  grants: [
    H.ops.workRead,
    H.ops.workUpdate,
    H.ops.workCancel,
    H.ops.blockersResolve,
    H.ops.memoryRead,
    H.ops.memoryWrite,
    H.ops.memoryCurate,
    H.ops.telemetryRead,
  ],
});

export const supportTriage = H.harness('support-triage')
  .ledger(sqlite.ledger({ path: '.harness/ledger.db' }))
  .lanes(conversations, escalations)
  .journals(supportTaste, supportExperience)
  .triggers(slaBreachEscalates, escalatedConversationNeedsHuman, reviewerNotesBecomeTaste)
  .metrics(humanApprovalByCategory, humanApprovalByModel)
  .scheduler(scheduler)
  .clients(supervisor)
  .observers(markdown.board({ path: '.harness/BOARD.md' }), markdown.telemetry({ path: '.harness/TELEMETRY.md' }));

void supportTriage.start();
=== END ===

=== FILE: scenarios/03-research-pipeline.ts ===
import { z } from 'zod';
import { H, type MetricRef } from 'harness-dsl';
import { sqlite } from 'harness-dsl/sqlite';
import { jsonl } from 'harness-dsl/jsonl';
import { pgvector } from 'harness-dsl/pgvector';
import { voyage } from 'harness-dsl/voyage';
import { anthropic } from 'harness-dsl/anthropic';
import { claudeCode } from 'harness-dsl/claude-code';
import { local } from 'harness-dsl/local';
import { markdown } from 'harness-dsl/markdown';

const storePath = '.harness/topics.db';
const topicCeilingUsd = 3;
const dailyBudgetUsd = 40;

const topicAttrs = z.object({ slug: z.string(), question: z.string(), tags: z.array(z.string()) });

const Queued = H.state('Queued', 'pending');
const Searching = H.state('Searching', 'active');
const Synthesizing = H.state('Synthesizing', 'active');
const Checking = H.state('Checking', 'active');
const Delivered = H.terminal('Delivered', 'success');
const Parked = H.terminal('Parked', 'neutral');
const Cancelled = H.terminal('Cancelled', 'neutral');
const Unresolvable = H.terminal('Unresolvable', 'failure');

const Topic = H.kind('Topic')
  .attributes(topicAttrs)
  .states(Queued, Searching, Synthesizing, Checking, Delivered, Parked, Cancelled, Unresolvable)
  .key((attrs) => attrs.slug)
  .initial(Queued)
  .onCancelled(Cancelled);

const searcherRole = H.role('searcher')
  .intents('search', 'browse')
  .instructions('Search for sources on one angle of the question and extract their claims.');
const synthesizerRole = H.role('synthesizer')
  .intents('read', 'record')
  .instructions(
    'Write a sourced report. State finding as "when researching X, start from Y, because Z". Set enoughSources false when the sources cannot support a report.',
  );

const apiAccount = anthropic.account('research-api', { apiKey: H.env('ANTHROPIC_API_KEY') });
const research = H.pool('research').accounts(apiAccount);

const haiku = anthropic.model('haiku', { id: 'claude-haiku-4-5' });
const sonnet = anthropic.model('sonnet', { id: 'claude-sonnet-4-5' });
const opus = anthropic.model('opus', { id: 'claude-opus-4-1' });

const synthesizerModel = H.policy.model('synthesizer-by-citation-pass-rate', [opus, sonnet], (ctx) => {
  const opusPass = ctx.metrics.rate(citationPass, { group: opus.name, window: { lastDays: 30 } });
  const sonnetPass = ctx.metrics.rate(citationPass, { group: sonnet.name, window: { lastDays: 30 } });
  if (opusPass.samples < 15) return opus;
  if (sonnetPass.samples < 15) return sonnet;
  return opusPass.rate >= sonnetPass.rate ? opus : sonnet;
});

const extraction = z.object({ source: z.string(), claims: z.array(z.string()) });
const report = z.object({
  enoughSources: z.boolean(),
  report: z.string(),
  citations: z.array(z.string()),
  finding: z.string(),
});

const searcher = H.agent('search-and-extract').role(searcherRole).model(haiku).pool(research).output(extraction);
const synthesizer = H.agent('synthesizer').role(synthesizerRole).model(synthesizerModel).pool(research).output(report);

const localRunner = local.runner('local');

const citationCheck = H.command('citation-check')
  .input(z.object({ citations: z.array(z.string()) }))
  .argv((input) => ['./tools/check-citations.sh', ...input.citations])
  .runner(localRunner);

const researchFlow = H.flow('research')
  .input(topicAttrs)
  .step('search', searcher.batch(), (ctx) =>
    Array.from({ length: 20 }, (_, index) => ({
      task: `Search angle ${index + 1} of 20 for: ${ctx.unit.attributes.question}`,
      skills: [ctx.unit.attributes.slug],
    })),
  )
  .step('synthesize', synthesizer, (ctx) => ({
    task: `Write a sourced report on: ${ctx.unit.attributes.question}\n\nExtractions:\n${ctx.steps.search
      .map((found) => `${found.source}: ${found.claims.join('; ')}`)
      .join('\n')}`,
    skills: [ctx.unit.attributes.slug],
  }))
  .exit('parked', (ctx) => !ctx.steps.synthesize.enoughSources)
  .step('citeCheck', citationCheck, (ctx) => ({ citations: ctx.steps.synthesize.citations }), { afterCrash: 'rerun' })
  .exit('delivered');

const topics = H.lane('topics', Topic)
  .supply(H.operator)
  .supply(
    sqlite.scan('recurring-topics', {
      path: storePath,
      kind: 'Topic',
      schedule: H.clock('weekly').at('06:00', { on: 'mon', tz: 'UTC' }),
    }),
    (stored, to) => {
      const parsed = topicAttrs.safeParse(stored.attributes);
      return parsed.success && parsed.data.tags.includes('recurring') ? to.create(parsed.data) : to.skip();
    },
  )
  .store(sqlite.store({ path: storePath }))
  .handler(researchFlow, {
    exits: { parked: Parked, delivered: Delivered },
    during: { search: Searching, synthesize: Synthesizing, citeCheck: Checking },
  })
  .retry({ maxAttempts: 2, backoff: 'exponential', initialDelayMs: 600_000, exhausted: Unresolvable })
  .ceiling({ maxUsd: topicCeilingUsd, onExceed: 'fail' });

const citationPass: MetricRef<'rate'> = H.metric(
  'citation-pass-by-synthesizer-model',
  H.when.step(topics, 'citeCheck'),
).samples((event) => [{ group: event.models.synthesize ?? 'unknown', hit: event.ok }]);

const researchSpend = H.metric('research-spend', H.when.invocation({ lanes: [topics] })).amounts((event) => [
  { group: 'all', amount: event.costUsd },
]);

const deliveredAttemptCost = H.metric(
  'delivered-attempt-cost',
  H.when.transition(topics, { to: Delivered }),
).amounts((event) => [{ group: 'all', amount: event.attempt?.costUsd ?? 0 }]);

const embedder = voyage.embedder('findings-embedder', { id: 'voyage-3', apiKey: H.env('VOYAGE_API_KEY') });

const findings = H.journal('report-findings', H.memory('finding', 'experience'))
  .store(pgvector.memoryStore({ url: H.env('RESEARCH_DATABASE_URL'), table: 'findings', embedder }))
  .recall({ by: 'similarity', limit: 6 })
  .readBy(synthesizerRole);

const sourceExperience = H.journal('source-experience', H.memory('source-experience', 'experience'))
  .store(jsonl.memoryStore({ path: '.harness/source-experience.jsonl' }))
  .recall({ by: 'specificity', limit: 10 })
  .readBy(searcherRole, synthesizerRole)
  .recordedBy(synthesizerRole);

const deliveredReportBecomesFinding = H.trigger('delivered-report-becomes-finding')
  .on(H.when.step(topics, 'citeCheck', { if: (event) => event.ok }))
  .record(findings, (event) => {
    const synthesis = event.outputs.synthesize;
    return synthesis === undefined
      ? undefined
      : {
          text: synthesis.finding,
          when: { kinds: [Topic], roles: [synthesizerRole], skills: [event.unit.attributes.slug] },
        };
  });

const scheduler = H.scheduler('research')
  .priority(topics)
  .admit(topics, (ctx) => {
    const spentToday = ctx.metrics.total(researchSpend, { window: { calendar: 'day', tz: 'UTC' } });
    const delivered = ctx.metrics.total(deliveredAttemptCost, { window: { lastDays: 30 } });
    const projectedUsd = delivered.samples === 0 ? topicCeilingUsd : delivered.total / delivered.samples;
    return spentToday.total + projectedUsd <= dailyBudgetUsd;
  });

const supervisor = claudeCode.supervisor('research-supervisor', {
  grants: [
    H.ops.workRead,
    H.ops.workCreate,
    H.ops.workCancel,
    H.ops.attemptsRecover,
    H.ops.memoryRead,
    H.ops.memoryCurate,
    H.ops.telemetryRead,
  ],
});

export const researchPipeline = H.harness('research-pipeline')
  .ledger(sqlite.ledger({ path: '.harness/ledger.db' }))
  .lanes(topics)
  .journals(findings, sourceExperience)
  .triggers(deliveredReportBecomesFinding)
  .metrics(citationPass, researchSpend, deliveredAttemptCost)
  .scheduler(scheduler)
  .clients(supervisor)
  .observers(markdown.board({ path: '.harness/BOARD.md' }), markdown.telemetry({ path: '.harness/TELEMETRY.md' }));

void researchPipeline.start();
=== END ===

