const drafterRole = H.role('drafter')
  .intents(['read'])
  .instructions('Draft the next reply to the customer.')
  .input({ subject: z.string(), comment: z.string(), category: z.string(), history: z.array(z.string()) })
  .output({ body: z.string() });

