  .supply([helpdeskWebhook, helpdeskPoll])
  .store(zendesk.store(Conversation, {
    ...connection,
    status: {
      New: 'new',
      Classifying: 'open',
      Drafting: 'open',
      AwaitingApproval: 'pending',
      Sent: 'solved',
      ClosedByCustomer: 'closed',
      Escalated: 'hold',
