      title: `Backup of ${e.unit.attributes.database} failed`,
      origin: `backup:${e.unit.key}`,
    },
  }));

const slowBackupMs = 2 * 3_600_000;

const slowBackup = H.trigger('slowBackup', H.on.transition(backups, { to: [BackedUp] }))
