  .attributes({ source: z.string(), night: z.string() })
  .states([Scheduled, Running, AwaitingApproval, Loaded, LoadedWithWarnings, Rejected, Expired, Failed])
  .timers(() => ({ approvalDeadline: H.time.daily('09:00', 'Europe/London') }))
  .failsTo(Failed)
